#!/usr/bin/env python3\n\"\"\"\n统一分析引擎综合测试脚本\n\n运行所有阶段的测试并生成综合报告\n\"\"\"\n\nimport os\nimport sys\nimport subprocess\nimport time\nimport json\nfrom datetime import datetime\nfrom typing import Dict, List, Any\n\n# 添加项目根目录到路径\nroot_dir = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\nsys.path.insert(0, root_dir)\n\nfrom utils.logger import get_logger\nfrom utils.path_utils import get_data_dir\n\nlogger = get_logger(__name__)\n\n\nclass TestSuiteRunner:\n    \"\"\"测试套件运行器\"\"\"\n    \n    def __init__(self):\n        self.test_results = {}\n        self.start_time = None\n        self.end_time = None\n        \n    def run_test_suite(self, test_module: str, test_name: str) -> Dict[str, Any]:\n        \"\"\"运行单个测试套件\"\"\"\n        logger.info(f\"🧪 开始运行测试套件: {test_name}\")\n        \n        start_time = time.time()\n        \n        try:\n            # 运行pytest\n            cmd = ['python', '-m', 'pytest', test_module, '-v', '--tb=short']\n            result = subprocess.run(\n                cmd, \n                capture_output=True, \n                text=True, \n                cwd=root_dir,\n                timeout=300  # 5分钟超时\n            )\n            \n            end_time = time.time()\n            duration = end_time - start_time\n            \n            # 解析结果\n            success = result.returncode == 0\n            output = result.stdout + result.stderr\n            \n            # 提取测试统计\n            stats = self._extract_test_stats(output)\n            \n            test_result = {\n                'name': test_name,\n                'module': test_module,\n                'success': success,\n                'duration': duration,\n                'stats': stats,\n                'output': output,\n                'timestamp': datetime.now().isoformat()\n            }\n            \n            if success:\n                logger.info(f\"✅ {test_name} 测试通过 ({duration:.2f}秒)\")\n            else:\n                logger.error(f\"❌ {test_name} 测试失败 ({duration:.2f}秒)\")\n                \n            return test_result\n            \n        except subprocess.TimeoutExpired:\n            logger.error(f\"⏰ {test_name} 测试超时\")\n            return {\n                'name': test_name,\n                'module': test_module,\n                'success': False,\n                'duration': 300,\n                'error': 'Timeout',\n                'timestamp': datetime.now().isoformat()\n            }\n            \n        except Exception as e:\n            logger.error(f\"💥 {test_name} 测试异常: {e}\")\n            return {\n                'name': test_name,\n                'module': test_module,\n                'success': False,\n                'duration': time.time() - start_time,\n                'error': str(e),\n                'timestamp': datetime.now().isoformat()\n            }\n    \n    def _extract_test_stats(self, output: str) -> Dict[str, int]:\n        \"\"\"从pytest输出中提取测试统计信息\"\"\"\n        stats = {\n            'passed': 0,\n            'failed': 0,\n            'errors': 0,\n            'skipped': 0,\n            'warnings': 0\n        }\n        \n        lines = output.split('\\n')\n        for line in lines:\n            if 'passed' in line and 'failed' in line:\n                # 解析类似 \"5 passed, 2 failed\" 的行\n                parts = line.split()\n                for i, part in enumerate(parts):\n                    if part.isdigit() and i + 1 < len(parts):\n                        count = int(part)\n                        status = parts[i + 1].rstrip(',')\n                        if status in stats:\n                            stats[status] = count\n            elif 'warnings summary' in line.lower():\n                stats['warnings'] = 1\n                \n        return stats\n    \n    def run_all_tests(self) -> Dict[str, Any]:\n        \"\"\"运行所有测试套件\"\"\"\n        logger.info(\"🚀 开始运行统一分析引擎综合测试\")\n        logger.info(\"=\" * 60)\n        \n        self.start_time = time.time()\n        \n        # 定义测试套件\n        test_suites = [\n            {\n                'module': 'tests/unit/engines/test_unified_indicator_engine.py',\n                'name': '阶段一：统一指标计算引擎'\n            },\n            {\n                'module': 'tests/unit/engines/test_shared_condition_evaluator.py',\n                'name': '阶段二：共享条件评估器'\n            },\n            {\n                'module': 'tests/test_complex_logic_processor.py',\n                'name': '阶段三：复杂逻辑处理器'\n            },\n            {\n                'module': 'tests/test_date_manager.py',\n                'name': '阶段四：智能日期管理器（单元测试）'\n            },\n            {\n                'module': 'tests/test_date_manager_integration.py',\n                'name': '阶段四：智能日期管理器（集成测试）'\n            },\n            {\n                'module': 'tests/test_indicator_validation_framework.py',\n                'name': '指标验证框架'\n            },\n            {\n                'module': 'tests/test_unified_analysis_engine_integration.py',\n                'name': '阶段五：系统集成测试'\n            }\n        ]\n        \n        # 运行各个测试套件\n        results = []\n        for suite in test_suites:\n            result = self.run_test_suite(suite['module'], suite['name'])\n            results.append(result)\n            self.test_results[suite['name']] = result\n            \n            # 如果是关键测试失败，考虑是否继续\n            if not result['success'] and '集成测试' not in suite['name']:\n                logger.warning(f\"⚠️ 关键测试 {suite['name']} 失败，但继续执行后续测试\")\n        \n        self.end_time = time.time()\n        \n        # 生成综合报告\n        report = self._generate_comprehensive_report(results)\n        \n        # 保存报告\n        self._save_report(report)\n        \n        return report\n    \n    def _generate_comprehensive_report(self, results: List[Dict[str, Any]]) -> Dict[str, Any]:\n        \"\"\"生成综合测试报告\"\"\"\n        total_duration = self.end_time - self.start_time\n        \n        # 统计总体情况\n        total_passed = sum(1 for r in results if r['success'])\n        total_failed = len(results) - total_passed\n        \n        # 统计测试用例\n        total_test_cases = 0\n        total_passed_cases = 0\n        total_failed_cases = 0\n        total_warnings = 0\n        \n        for result in results:\n            if 'stats' in result:\n                stats = result['stats']\n                total_test_cases += sum(stats.values())\n                total_passed_cases += stats.get('passed', 0)\n                total_failed_cases += stats.get('failed', 0) + stats.get('errors', 0)\n                total_warnings += stats.get('warnings', 0)\n        \n        # 计算成功率\n        success_rate = (total_passed / len(results)) * 100 if results else 0\n        case_success_rate = (total_passed_cases / total_test_cases) * 100 if total_test_cases > 0 else 0\n        \n        report = {\n            'summary': {\n                'total_suites': len(results),\n                'passed_suites': total_passed,\n                'failed_suites': total_failed,\n                'success_rate': success_rate,\n                'total_duration': total_duration,\n                'timestamp': datetime.now().isoformat()\n            },\n            'test_cases': {\n                'total_cases': total_test_cases,\n                'passed_cases': total_passed_cases,\n                'failed_cases': total_failed_cases,\n                'case_success_rate': case_success_rate,\n                'warnings': total_warnings\n            },\n            'detailed_results': results,\n            'recommendations': self._generate_recommendations(results)\n        }\n        \n        return report\n    \n    def _generate_recommendations(self, results: List[Dict[str, Any]]) -> List[str]:\n        \"\"\"生成改进建议\"\"\"\n        recommendations = []\n        \n        # 检查失败的测试\n        failed_tests = [r for r in results if not r['success']]\n        if failed_tests:\n            recommendations.append(f\"有 {len(failed_tests)} 个测试套件失败，需要优先修复\")\n            for test in failed_tests:\n                recommendations.append(f\"- 修复 {test['name']} 的问题\")\n        \n        # 检查性能问题\n        slow_tests = [r for r in results if r.get('duration', 0) > 60]\n        if slow_tests:\n            recommendations.append(\"以下测试执行时间较长，建议优化：\")\n            for test in slow_tests:\n                recommendations.append(f\"- {test['name']}: {test['duration']:.2f}秒\")\n        \n        # 检查警告\n        warning_tests = [r for r in results if r.get('stats', {}).get('warnings', 0) > 0]\n        if warning_tests:\n            recommendations.append(\"以下测试有警告信息，建议处理：\")\n            for test in warning_tests:\n                recommendations.append(f\"- {test['name']}\")\n        \n        if not recommendations:\n            recommendations.append(\"🎉 所有测试都通过了，系统状态良好！\")\n        \n        return recommendations\n    \n    def _save_report(self, report: Dict[str, Any]) -> None:\n        \"\"\"保存测试报告\"\"\"\n        try:\n            # 保存JSON格式报告\n            data_dir = get_data_dir()\n            result_dir = os.path.join(data_dir, 'result')\n            os.makedirs(result_dir, exist_ok=True)\n            \n            timestamp = datetime.now().strftime('%Y%m%d_%H%M%S')\n            json_file = os.path.join(result_dir, f'test_report_{timestamp}.json')\n            \n            with open(json_file, 'w', encoding='utf-8') as f:\n                json.dump(report, f, ensure_ascii=False, indent=2)\n            \n            logger.info(f\"📊 测试报告已保存: {json_file}\")\n            \n            # 生成并保存文本格式报告\n            text_report = self._generate_text_report(report)\n            text_file = os.path.join(result_dir, f'test_report_{timestamp}.txt')\n            \n            with open(text_file, 'w', encoding='utf-8') as f:\n                f.write(text_report)\n            \n            logger.info(f\"📄 文本报告已保存: {text_file}\")\n            \n        except Exception as e:\n            logger.error(f\"保存测试报告失败: {e}\")\n    \n    def _generate_text_report(self, report: Dict[str, Any]) -> str:\n        \"\"\"生成文本格式的测试报告\"\"\"\n        lines = []\n        lines.append(\"=\" * 80)\n        lines.append(\"统一分析引擎综合测试报告\")\n        lines.append(\"=\" * 80)\n        lines.append(f\"生成时间: {report['summary']['timestamp']}\")\n        lines.append(f\"总执行时间: {report['summary']['total_duration']:.2f}秒\")\n        lines.append(\"\")\n        \n        # 总体统计\n        summary = report['summary']\n        lines.append(\"📊 总体统计\")\n        lines.append(\"-\" * 40)\n        lines.append(f\"测试套件总数: {summary['total_suites']}\")\n        lines.append(f\"通过套件数: {summary['passed_suites']}\")\n        lines.append(f\"失败套件数: {summary['failed_suites']}\")\n        lines.append(f\"套件成功率: {summary['success_rate']:.1f}%\")\n        lines.append(\"\")\n        \n        # 测试用例统计\n        cases = report['test_cases']\n        lines.append(\"🧪 测试用例统计\")\n        lines.append(\"-\" * 40)\n        lines.append(f\"测试用例总数: {cases['total_cases']}\")\n        lines.append(f\"通过用例数: {cases['passed_cases']}\")\n        lines.append(f\"失败用例数: {cases['failed_cases']}\")\n        lines.append(f\"用例成功率: {cases['case_success_rate']:.1f}%\")\n        lines.append(f\"警告数量: {cases['warnings']}\")\n        lines.append(\"\")\n        \n        # 详细结果\n        lines.append(\"📋 详细测试结果\")\n        lines.append(\"-\" * 40)\n        for result in report['detailed_results']:\n            status = \"✅ 通过\" if result['success'] else \"❌ 失败\"\n            duration = result.get('duration', 0)\n            lines.append(f\"{status} {result['name']} ({duration:.2f}秒)\")\n            \n            if 'stats' in result:\n                stats = result['stats']\n                if stats.get('passed', 0) > 0 or stats.get('failed', 0) > 0:\n                    lines.append(f\"    测试用例: {stats.get('passed', 0)}通过, {stats.get('failed', 0)}失败\")\n        \n        lines.append(\"\")\n        \n        # 改进建议\n        lines.append(\"💡 改进建议\")\n        lines.append(\"-\" * 40)\n        for rec in report['recommendations']:\n            lines.append(rec)\n        \n        lines.append(\"\")\n        lines.append(\"=\" * 80)\n        \n        return \"\\n\".join(lines)\n    \n    def print_summary(self, report: Dict[str, Any]) -> None:\n        \"\"\"打印测试摘要\"\"\"\n        print(\"\\n\" + \"=\" * 60)\n        print(\"🎯 统一分析引擎测试完成\")\n        print(\"=\" * 60)\n        \n        summary = report['summary']\n        cases = report['test_cases']\n        \n        print(f\"📊 总体情况:\")\n        print(f\"   • 测试套件: {summary['passed_suites']}/{summary['total_suites']} 通过 ({summary['success_rate']:.1f}%)\")\n        print(f\"   • 测试用例: {cases['passed_cases']}/{cases['total_cases']} 通过 ({cases['case_success_rate']:.1f}%)\")\n        print(f\"   • 执行时间: {summary['total_duration']:.2f}秒\")\n        \n        if summary['failed_suites'] > 0:\n            print(f\"\\n⚠️ 失败的测试套件:\")\n            for result in report['detailed_results']:\n                if not result['success']:\n                    print(f\"   • {result['name']}\")\n        \n        print(f\"\\n💡 改进建议:\")\n        for rec in report['recommendations'][:3]:  # 只显示前3个建议\n            print(f\"   • {rec}\")\n        \n        print(\"\\n\" + \"=\" * 60)\n\n\ndef main():\n    \"\"\"主函数\"\"\"\n    runner = TestSuiteRunner()\n    \n    try:\n        report = runner.run_all_tests()\n        runner.print_summary(report)\n        \n        # 返回适当的退出码\n        if report['summary']['failed_suites'] > 0:\n            sys.exit(1)\n        else:\n            sys.exit(0)\n            \n    except KeyboardInterrupt:\n        logger.info(\"\\n⏹️ 测试被用户中断\")\n        sys.exit(130)\n    except Exception as e:\n        logger.error(f\"测试运行异常: {e}\")\n        sys.exit(1)\n\n\nif __name__ == '__main__':\n    main() 